-- +goose Up
ON CONFLICT (slug) DO NOTHING;

UPDATE scenario_topics SET short_name = CASE slug
  WHEN 'job-interviews' THEN 'Job interviews'
  WHEN 'architecture-reviews' THEN 'Architecture reviews'
  WHEN 'cross-functional-sync' THEN 'Stakeholder sync'
  WHEN 'product-pitch' THEN 'Product pitch' END
WHERE slug IN ('job-interviews','architecture-reviews','cross-functional-sync','product-pitch')
  AND short_name = '';

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

-- Pre-existing rows (e.g. custom scenarios created before the column
-- existed) carry their cap in details: promote it so the column stays the
-- single source of truth. Seed rows above have no duration keys and are
-- untouched by both updates.
UPDATE scenarios SET max_duration = (details->>'max_duration')::int
WHERE details ? 'max_duration';
UPDATE scenarios SET max_duration = (details->>'duration_max')::int
WHERE details ? 'duration_max' AND NOT (details ? 'max_duration');

