 ('9735face-d870-5b51-ae3a-e18768a282fc','architecture-reviews','Topic 2: Architecture & system design reviews','Architecture reviews',2),
 ('30f6d380-0aef-54ef-873f-ef99831d08fa','cross-functional-sync','Topic 3: Cross-functional sync & stakeholder collaboration','Stakeholder sync',3),
 ('feb75488-7550-5975-bf8f-8d981554ee43','product-pitch','Topic 4: Product pitch & executive presentation','Product pitch',4)
INSERT INTO personas (id, name, role_title, personality, style, objective, default_cefr) VALUES
 ('1833728f-f95c-548b-9ba9-a9b80d91b201','Amelia','Hiring director','Warm but exacting','Structured behavioural interviews','Assess leadership stories for measurable outcomes','B2'),
 ('3c175399-77b3-57b8-bb31-e6f7d26c0038','Marcus','Senior interviewer','Direct, evidence-driven','Post-mortem questioning','Test how you handle past failure and learning','B2'),
 ('29fafa99-87f4-51d3-8a79-99bec3d2b9dc','Priya','VP of Talent','Polished negotiator','Executive compensation talks','Reach a defensible compensation agreement','C1'),
 ('3f3904e5-2e6e-5de4-8b5a-038e075cc30c','Sarah','Staff engineer','Analytical, sceptical','Architecture design review','Stress-test the caching and failover decisions','C1'),
 ('473d21cd-6a87-5e3a-b4eb-b9638b9d2bb2','Tom','Product manager','Pragmatic, deadline-driven','Roadmap negotiation','Rebalance scope against the committed timeline','B2'),
 ('5724c95c-9eda-5978-8cc6-7ce306a48102','Diego','Head of Infrastructure','Calm under pressure','Incident post-mortem','Establish preventive measures without blame','C1'),
 ('3292d7be-0dac-59ef-8c55-458d4b25dad3','Rachel','Enterprise client VP','Frustrated but fair','Escalation management','Restore trust with a credible remediation plan','B1'),
 ('e92c52ab-07c8-55ed-8d85-1fcd702abfbc','Omar','Procurement lead','Numbers-first','Commercial renegotiation','Protect margin while adjusting scope','C1'),
 ('5e8a480c-e05e-566f-b0d7-9fc7c614c07d','Yuki','Design VP','Visionary, user-obsessed','Design-engineering alignment','Find a pragmatic compromise on the roadmap','B2'),
 ('a3dc4a1f-9900-5868-8f0e-0a051f4d030b','Elena','Managing Director','Strategic, time-poor','Executive demo review','Judge narrative clarity and value framing','C1'),
 ('3d325036-1e34-59ba-8c1f-cca26503a292','Nathan','Angel Investor','Sceptical, detail-hungry','Investor Q&A','Interrogate unit economics and defensibility','B2'),
 ('585cec08-dc6b-5def-9daa-02a6a5ebd826','Charles','Board Member','Formal, governance-minded','Board strategy review','Justify headcount and infrastructure spend','C1')
INSERT INTO scenarios (id, topic_id, persona_id, title, objective, cefr_level, max_duration, details, user_id) VALUES
 ('01b9a032-e2cf-5bb0-8df5-7bf49704bee8','6fd75995-c652-5709-bcfe-d7204c23ab56','1833728f-f95c-548b-9ba9-a9b80d91b201','Behavioral questions on leadership','Articulate cross-functional conflict resolution using structured STAR methodology and leadership poise.','B2',10,$json$ {"context": ["You are interviewing for an engineering manager role. Amelia wants evidence of how you handle disagreement between your team and a partner team, not generalities.", "She scores answers told as complete stories: situation, task, action, result — with measurable outcomes."], "opening": {"label": "Amelia (Opening statement):", "text": "Tell me about a time you resolved a conflict between your team and another team. What was the outcome?"}, "role": "Engineering manager", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Hiring director", "vocab": ["STAR", "ownership", "trade-off", "alignment"]} $json$,NULL),
 ('aea304e9-1232-55d9-8047-1eceb378ec88','6fd75995-c652-5709-bcfe-d7204c23ab56','3c175399-77b3-57b8-bb31-e6f7d26c0038','Explaining project failure & learnings','Address past technical mistakes objectively while emphasizing post-mortem remediation and growth mindset.','B2',8,$json$ {"context": ["Marcus runs post-mortem style interviews: he wants the unvarnished story of something you shipped that failed.", "Defensiveness fails instantly. He rewards ownership, root-cause clarity, and concrete prevention."], "opening": {"label": "Marcus (Opening statement):", "text": "Walk me through a project that failed on your watch. What went wrong?"}, "role": "Backend engineer", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Senior interviewer", "vocab": ["post-mortem", "root cause", "remediation", "blameless"]} $json$,NULL),
 ('65b80111-4e6d-5839-bb6b-2afc46a48079','6fd75995-c652-5709-bcfe-d7204c23ab56','29fafa99-87f4-51d3-8a79-99bec3d2b9dc','Salary negotiation with hiring director','Advocate for market-rate equity and base compensation with diplomatic firmness and polished leverage framing.','C1',12,$json$ {"context": ["You have an offer below market. Priya is a polished negotiator: she anchors low and trades slowly.", "Your leverage is a competing timeline and documented market data. Never disclose your current salary first."], "opening": {"label": "Priya (Opening statement):", "text": "We are excited to move forward. The offer is competitive for the band — what would it take to close?"}, "role": "Senior engineer", "goal_format": "3–4 turns dialogue", "interlocutor_role": "VP of Talent", "vocab": ["band", "equity", "leverage", "competing offer"]} $json$,NULL),
 ('9f23a64d-793f-5810-8f61-a1b4100ef19b','9735face-d870-5b51-ae3a-e18768a282fc','3f3904e5-2e6e-5de4-8b5a-038e075cc30c','Architectural RFC & database tradeoff defense','Defend distributed database partitioning schemes against concurrency challenges and latency trade-offs.','C1',10,$json$ {"context": ["Your RFC proposes range partitioning for the orders table. Sarah is sceptical: she will probe hot partitions, cross-shard transactions, and failover.", "Hand-waving fails. She expects numbers: key cardinality, p99 estimates, rebalance cost."], "opening": {"label": "Sarah (Opening statement):", "text": "Convince me range partitioning survives a hot tenant without turning every write into a cross-shard transaction."}, "role": "Backend engineer", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Staff engineer", "vocab": ["partition key", "hotspot", "consistency", "failover"]} $json$,NULL),
 ('3a8b3191-c8a3-5855-8e05-0a268cedac3e','9735face-d870-5b51-ae3a-e18768a282fc','473d21cd-6a87-5e3a-b4eb-b9638b9d2bb2','Sprint retrospective & timeline pushback','Negotiate realistic engineering delivery milestones while articulating tech debt risks constructively.','B2',8,$json$ {"context": ["Your team had committed to finishing the v2 Billing API migration by the end of Sprint 42. However, unexpected replication lag on the read-replica database forced your team to pause automated schema rollouts and implement upstream backpressure.", "During this sprint retro, Tom (Product manager) asks why user-facing release notes are delayed by two weeks, and whether engineering could simply ship now and fix the edge cases next week."], "opening": {"label": "Tom (Opening statement):", "text": "We committed to leadership that the billing migration would wrap this week. Can you walk us through what caused the slip, and why we cannot just cut scope on the edge cases and ship tomorrow?"}, "role": "Tech Lead / Senior Eng", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Product Manager", "vocab": ["idempotent", "backpressure", "replication lag", "read-replica"]} $json$,NULL),
 ('d468966c-8081-5ec9-a2bd-3b2431bfe516','9735face-d870-5b51-ae3a-e18768a282fc','5724c95c-9eda-5978-8cc6-7ce306a48102','API outage post-mortem with leads','Walk through root-cause analysis transparently and articulate systematic preventive measures without panic.','C1',9,$json$ {"context": ["Last night the payments API went down for 47 minutes. Diego runs blameless post-mortems, but he expects precision: timeline, detection gap, and the fix that prevents recurrence.", "Minimizing the impact will backfire. He already has the status page data."], "opening": {"label": "Diego (Opening statement):", "text": "Walk me through last night minute by minute. When did we first know, and why did it take 47 minutes?"}, "role": "On-call engineer", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Head of Infrastructure", "vocab": ["post-mortem", "runbook", "alert fatigue", "rollback"]} $json$,NULL),
 ('dca3ffa8-7f11-5846-a2f5-abc717e5240f','30f6d380-0aef-54ef-873f-ef99831d08fa','3292d7be-0dac-59ef-8c55-458d4b25dad3','De-escalating enterprise client incident','Calm frustrated enterprise accounts with clear empathy, transparent SLA compensation, and action timelines.','B1+',7,$json$ {"context": ["Your largest enterprise account hit a full outage during their peak sales hour. Rachel is frustrated but fair: she wants honesty, not scripts.", "You can offer SLA credit and a remediation timeline, but you cannot promise it will never happen again."], "opening": {"label": "Rachel (Opening statement):", "text": "Our checkout was down for an hour at peak. My team is asking hard questions — give me something real to take back to them."}, "role": "Support engineer", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Enterprise client VP", "vocab": ["SLA", "compensation", "remediation", "timeline"]} $json$,NULL),
 ('b5bc17c1-93d9-5db8-8bd9-7ef5dbb1e817','30f6d380-0aef-54ef-873f-ef99831d08fa','e92c52ab-07c8-55ed-8d85-1fcd702abfbc','Budget scope renegotiation','Protect project margin while offering creative tiered deliverable options under constrained budget realities.','C1',9,$json$ {"context": ["Finance cut the project budget by 30% mid-flight. Omar is numbers-first: every scope item must map to money.", "Cutting quality silently is not an option. Tiered deliverables keep margin defensible."], "opening": {"label": "Omar (Opening statement):", "text": "The budget is down 30%. Show me what we cut and what the margin looks like after."}, "role": "Engineering lead", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Procurement lead", "vocab": ["margin", "tiered", "scope", "baseline"]} $json$,NULL),
 ('6fb1326f-6b4a-5299-b24f-7e16d1092583','30f6d380-0aef-54ef-873f-ef99831d08fa','5e8a480c-e05e-566f-b0d7-9fc7c614c07d','Aligning design roadmap with VP','Synthesize engineering constraints with design vision, proposing pragmatic compromises without sacrificing user delight.','B2',10,$json$ {"context": ["Yuki wants a bold redesign for the flagship flow; your team says the timeline only allows iteration. Both positions are legitimate.", "Dismissing the vision kills trust; promising it all burns the team. The compromise must be concrete."], "opening": {"label": "Yuki (Opening statement):", "text": "The redesign is the differentiator next quarter. Why is engineering pushing back on the vision?"}, "role": "Frontend engineer", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Design VP", "vocab": ["roadmap", "iteration", "delight", "feasibility"]} $json$,NULL),
 ('f6868fca-cdd9-56c2-a484-3a109f69c22a','feb75488-7550-5975-bf8f-8d981554ee43','a3dc4a1f-9900-5868-8f0e-0a051f4d030b','Product launch & vision demo','Pitch strategic AI initiatives to executive leadership with high narrative engagement and clear value propositions.','C1',12,$json$ {"context": ["You have ten minutes with Elena, who is strategic and time-poor. She funds narratives tied to revenue, not technology demos.", "Every feature you show must answer: what changes for the business this quarter?"], "opening": {"label": "Elena (Opening statement):", "text": "You have ten minutes. Why should this AI initiative get funded over everything else competing for the budget?"}, "role": "Product engineer", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Managing Director", "vocab": ["value proposition", "narrative", "traction", "runway"]} $json$,NULL),
 ('01bc0e94-82ad-5055-a147-e3ce0bd4beaa','feb75488-7550-5975-bf8f-8d981554ee43','3d325036-1e34-59ba-8c1f-cca26503a292','Handling tough investor Q&A','Address unit economics, market churn risks, and competitive defensibility while staying composed under pressure.','B2',10,$json$ {"context": ["Nathan is sceptical and detail-hungry: he has read your deck and found the weak spots in unit economics and churn.", "Defensiveness reads as hiding. He respects founders who know their numbers cold, including the bad ones."], "opening": {"label": "Nathan (Opening statement):", "text": "Your CAC payback went the wrong way two quarters running. Why should I believe it turns around?"}, "role": "Founder", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Angel Investor", "vocab": ["unit economics", "churn", "CAC", "defensibility"]} $json$,NULL),
 ('395b40a9-a2bb-5c53-bbdf-3e808efa527a','feb75488-7550-5975-bf8f-8d981554ee43','585cec08-dc6b-5def-9daa-02a6a5ebd826','Annual strategy & budget defense','Articulate headcount growth and infrastructure spend return on investment with authoritative clarity.','C1',15,$json$ {"context": ["Charles is formal and governance-minded: headcount and infrastructure spend must each show return on investment.", "Passion does not persuade him. Structure, precedent, and numbers do."], "opening": {"label": "Charles (Opening statement):", "text": "You are asking for 40% more headcount and double the infrastructure budget. Justify both, starting with the return."}, "role": "Engineering director", "goal_format": "3–4 turns dialogue", "interlocutor_role": "Board Member", "vocab": ["ROI", "headcount", "runway", "governance"]} $json$,NULL)
